package studio.solocamera;

import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import java.io.*;import java.lang.reflect.*;

final class TitleLibraryChecks {
 private static void check(boolean ok,String label){if(!ok)throw new AssertionError(label);}
 private static void set(Object a,String n,Object v)throws Exception{Field f=a.getClass().getDeclaredField(n);f.setAccessible(true);f.set(a,v);}
 private static Object get(Object a,String n)throws Exception{Field f=a.getClass().getDeclaredField(n);f.setAccessible(true);return f.get(a);}
 private static void call(Object a,String n)throws Exception{Method m=a.getClass().getDeclaredMethod(n);m.setAccessible(true);m.invoke(a);}
 interface Action{void run()throws Exception;}
 private static void ui(Instrumentation host,Action action){Throwable[] error={null};host.runOnMainSync(()->{try{action.run();}catch(Throwable e){error[0]=e;}});if(error[0]!=null)throw new RuntimeException(error[0]);}
 private static void click(Instrumentation host,String text,boolean exact)throws Exception{long until=SystemClock.elapsedRealtime()+8000;while(SystemClock.elapsedRealtime()<until){var root=host.getUiAutomation().getRootInActiveWindow();if(root!=null)for(var node:root.findAccessibilityNodeInfosByText(text)){String value=node.getText()==null?"":node.getText().toString();if(!exact||text.equalsIgnoreCase(value)){while(node!=null&&!node.isClickable())node=node.getParent();if(node==null)continue;node.performAction(android.view.accessibility.AccessibilityNodeInfo.AccessibilityAction.ACTION_SHOW_ON_SCREEN.getId());Thread.sleep(150);if(node.performAction(android.view.accessibility.AccessibilityNodeInfo.ACTION_CLICK)){Thread.sleep(300);return;}}}Thread.sleep(200);}throw new AssertionError("Missing button: "+text);}
 private static void image(File dir,String name,Bitmap bitmap)throws Exception{try(FileOutputStream stream=new FileOutputStream(new File(dir,name))){bitmap.compress(Bitmap.CompressFormat.PNG,100,stream);}}
 static void run(Instrumentation host,Bundle result)throws Exception{
  host.startActivitySync(new Intent(host.getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));android.os.Bundle progress=new android.os.Bundle();progress.putString("stage","Rendering static designs");host.sendStatus(0,progress);EditorFonts.init(host.getTargetContext());File dir=new File(host.getTargetContext().getCacheDir(),"title-library-qa");dir.mkdirs();int[] counts=new int[8];
  for(int id=0;id<EditorTitlePresets.NAMES.length;id++){counts[EditorTitlePresets.group(id)]++;EditorProject.Clip c=EditorTitlePresets.create(id,4000);EditorProject.Clip restored=EditorProject.Clip.from(c.json());check(restored.titleDesign==id+1&&restored.designSubtitle.equals(c.designSubtitle)&&restored.designAccent==c.designAccent,"Preset serialization "+id);check(EditorMotion.sample(c,0,true).alpha<.000001&&EditorMotion.sample(c,2000,true).alpha>.99&&EditorMotion.sample(c,4000,true).alpha==0,"Preset animation "+id);for(int[] size:new int[][]{{640,360},{360,640}}){Bitmap b=EditorText.bitmap(restored,size[0],size[1]);check(b.getWidth()>0&&b.getWidth()<=size[0]&&b.getHeight()>0&&b.getHeight()<=size[1],"Preset size "+id);EditorMotion.Key placed=EditorMotion.sample(restored,2000,true);double center=size[1]*(1-placed.y)/2;check(center-b.getHeight()/2.0>=-1&&center+b.getHeight()/2.0<=size[1]+1,"Preset outside safe frame "+id);if(size[0]==640)image(dir,String.format(java.util.Locale.US,"preset-%02d.png",id),b);b.recycle();}}
  progress.putString("stage","Rendering component animation checks");host.sendStatus(0,progress);for(int id=0;id<EditorTitlePresets.NAMES.length;id++){EditorProject.Clip c=EditorTitlePresets.create(id,4000);EditorTitleAnimation animation=new EditorTitleAnimation(c,360,640);try{Bitmap start=animation.frame(0,4000);check(Color.alpha(start.getPixel(start.getWidth()/2,start.getHeight()/2))==0,"Animation starts clear "+id);Bitmap early=animation.frame(130,4000).copy(Bitmap.Config.ARGB_8888,false);Bitmap middle=animation.frame(1300,4000);check(!early.sameAs(middle),"Components do not animate "+id);Bitmap full=EditorText.bitmap(c,360,640);long delta=0,bad=0;for(int yy=0;yy<full.getHeight();yy++)for(int xx=0;xx<full.getWidth();xx++){int a=full.getPixel(xx,yy),b=middle.getPixel(xx,yy);int d=Math.abs(Color.alpha(a)-Color.alpha(b))+Math.abs(Color.red(a)-Color.red(b))+Math.abs(Color.green(a)-Color.green(b))+Math.abs(Color.blue(a)-Color.blue(b));delta+=d;if(d>16)bad++;}long pixels=(long)full.getWidth()*full.getHeight();check(EditorProfessionTitles.profession(id)||(delta<pixels*2&&bad<pixels/1000+1),"Animated settled layout differs "+id+" delta="+delta+" bad="+bad+" pixels="+pixels);early.recycle();full.recycle();Bitmap end=animation.frame(4000,4000);check(Color.alpha(end.getPixel(end.getWidth()/2,end.getHeight()/2))==0,"Animation ends clear "+id);}finally{animation.release();}}
  check(counts[1]==12&&counts[2]==8&&counts[3]==12&&counts[4]==8&&counts[5]==36&&counts[6]==12&&counts[7]==50,"Category counts");check(EditorFontLibrary.catalog(host.getTargetContext()).length()==9,"Optional font catalog missing");EditorProject project=new EditorProject();project.id="33333333-3333-4333-8333-333333333346";project.name="Title library QA";project.aspect=2;project.height=720;for(int i=0;i<2;i++){EditorProject.Caption item=new EditorProject.Caption();item.type="Text";item.style=EditorTitlePresets.create(i==0?20:0,2500);item.at=i*2500;item.end=item.at+2500;item.track=i;project.captions.add(item);}EditorProject.Caption social=new EditorProject.Caption();social.type="Text";social.style=EditorTitlePresets.create(40,2500);social.style.designSubtitle="@solocreator";social.at=0;social.end=2500;social.track=2;project.captions.add(social);check(EditorProject.from(project.json().toString()).duration()==5000,"Slides-only project timing");
  progress.putString("stage","Opening editor");host.sendStatus(0,progress);EditorActivity a=(EditorActivity)host.startActivitySync(new Intent(host.getTargetContext(),EditorActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));try{progress.putString("stage","Opening title browser");host.sendStatus(0,progress);ui(host,()->{set(a,"project",project);set(a,"editing",true);set(a,"selectedCaption",0);set(a,"selectedTrack","Text");set(a,"position",1000L);call(a,"showEditor");call(a,"titleLibrary");});Thread.sleep(800);Bitmap browser=host.getUiAutomation().takeScreenshot();image(dir,"library-screen.png",browser);browser.recycle();click(host,"Professions",true);click(host,"All professions ▾",true);click(host,"Technology",true);Bitmap professionBrowser=host.getUiAutomation().takeScreenshot();image(dir,"profession-filter-screen.png",professionBrowser);professionBrowser.recycle();click(host,"All",true);click(host,"Studio signature",false);Thread.sleep(500);android.view.accessibility.AccessibilityNodeInfo root=host.getUiAutomation().getRootInActiveWindow();boolean edited=false;for(var node:root.findAccessibilityNodeInfosByText("Alex Morgan")){if("android.widget.EditText".contentEquals(node.getClassName())){Bundle value=new Bundle();value.putCharSequence(android.view.accessibility.AccessibilityNodeInfo.ACTION_ARGUMENT_SET_TEXT_CHARSEQUENCE,"Jordan Reed");edited=node.performAction(android.view.accessibility.AccessibilityNodeInfo.ACTION_SET_TEXT,value);break;}}check(edited,"Cannot edit preset headline");click(host,"More fonts",false);if(!EditorFontLibrary.file(a,"oswald").exists()){click(host,"Oswald",false);click(host,"Cancel",true);check(!EditorFontLibrary.file(a,"oswald").exists(),"Canceled font installed");click(host,"Oswald",false);click(host,"Download",true);}else click(host,"Oswald",false);long downloadEnd=SystemClock.elapsedRealtime()+25000;while(!EditorFontLibrary.file(a,"oswald").exists()&&SystemClock.elapsedRealtime()<downloadEnd)Thread.sleep(250);check(EditorFontLibrary.file(a,"oswald").exists(),"Optional Oswald font did not download");Thread.sleep(700);Bitmap customize=host.getUiAutomation().takeScreenshot();image(dir,"customize-screen.png",customize);customize.recycle();click(host,"Add to timeline",false);check(project.captions.size()==4&&project.captions.get(3).style.text.equals("Jordan Reed")&&project.captions.get(3).style.font.startsWith("file:"),"Preset insertion lost text or downloaded font");progress.putString("stage","Exporting MP4");host.sendStatus(0,progress);ui(host,()->call(a,"startExport"));boolean[] busy={true};long until=SystemClock.elapsedRealtime()+90000;while(busy[0]&&SystemClock.elapsedRealtime()<until){Thread.sleep(300);ui(host,()->busy[0]=(Boolean)get(a,"exporting"));}ui(host,()->{check(!busy[0]&&get(a,"lastExport")!=null,"Slides-only title export failed");result.putString("exportUri",get(a,"lastExport").toString());});
   android.media.MediaMetadataRetriever media=new android.media.MediaMetadataRetriever();try{media.setDataSource(host.getTargetContext(),android.net.Uri.parse(result.getString("exportUri")));Bitmap frame=media.getFrameAtTime(1_000_000,android.media.MediaMetadataRetriever.OPTION_CLOSEST);check(frame!=null,"Export frame unavailable");image(dir,"exported-slide.png",frame);long red=0;long nonBlack=0;for(int y=0;y<frame.getHeight();y+=5)for(int x=0;x<frame.getWidth();x+=5){int pixel=frame.getPixel(x,y);if((pixel&0xffffff)>0x202020)nonBlack++;if(Color.red(pixel)>150&&Color.green(pixel)<100&&Color.blue(pixel)<100)red++;}check(nonBlack>200,"Export missing slide graphics");check(red>50,"Export missing YouTube brand badge");frame.recycle();}finally{media.release();}
   result.putString("checks","PASS 138 designs x landscape/portrait, JSON, staggered component entrance/settled/exit frames, font catalog, download/cancel and live customization, visual browser, slides-only MP4 and decoded slide graphics");
  }finally{ui(host,a::finish);new File(host.getTargetContext().getFilesDir(),"edit-projects/"+project.id+".json").delete();}
 }
}
